import test from "node:test";
import assert from "node:assert/strict";
import {apply, planner} from "./replay.mjs";

const catalog = {default: 5, studios: new Map([["orchid", 8], ["iris", 3]])};
const book = (id, units, tenant = "orchid", day = "2025-04-02") =>
  ({service:"studio", action:"book", id, tenant, units, day});

test("Studio allocations are tenant/day scoped and Archive keeps the default", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(book("first", 7)), {status:"booked", id:"first", remaining:1});
  assert.equal(dispatch(book("overflow", 2)).status, "full");
  assert.equal(dispatch(book("last", 1)).remaining, 0);
  assert.equal(dispatch(book("tomorrow", 8, "orchid", "2025-04-03")).status, "booked");
  assert.equal(dispatch(book("smaller", 4, "iris")).status, "full");
  assert.equal(dispatch(book("iris", 3, "iris")).remaining, 0);
  assert.equal(dispatch(book("default-over", 6, "unlisted")).status, "full");
  assert.equal(dispatch(book("default", 5, "unlisted")).remaining, 0);
  assert.equal(dispatch({...book("archive-over", 6), service:"archive"}).status, "full");
  assert.equal(dispatch({...book("archive", 5), service:"archive"}).remaining, 0);
});

test("Studio keeps replay, conflict, cancellation and imported usage semantics", () => {
  const dispatch = planner(catalog);
  const request = book("original", 7);
  dispatch(request);
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units:8}).status, "conflict");
  assert.equal(dispatch({service:"studio", action:"summary"}).events.length, 1);
  assert.equal(dispatch({service:"studio", action:"cancel", id:request.id}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:request.id}).status, "replay");
  assert.equal(dispatch({...book("backfill", 6), action:"import"}).status, "imported");
  assert.equal(dispatch(book("too-much", 3)).status, "full");
  assert.equal(dispatch(book("fits", 2)).remaining, 0);
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:request.day}), {units:8});
  assert.deepEqual(apply(dispatch, book("invalid", 0)), {status:"invalid", field:"units"});
});

test("monthly renewals use the same allowance and lifecycle rules", () => {
  const dispatch = planner(catalog);
  dispatch(book("previous", 7));
  const next = {service:"studio", action:"renew", previous:"previous", id:"next", day:"2025-05-02"};
  assert.deepEqual(dispatch(next), {status:"booked", id:"next", remaining:1});
  assert.equal(dispatch(next).status, "replay");
  assert.equal(dispatch({...next, units:8}).status, "conflict");
  assert.equal(dispatch({...next, id:"extra", units:2}).status, "full");
  dispatch({service:"studio", action:"cancel", id:"next"});
  assert.equal(dispatch(next).status, "cancelled");
  assert.equal(dispatch({...next, id:"replacement", units:8}).remaining, 0);
  assert.equal(dispatch({...next, previous:"next", id:"inactive"}).status, "missing");
  dispatch(book("fallback", 5, "unlisted"));
  assert.equal(dispatch({...next, previous:"fallback", id:"fallback-over", units:6}).status, "full");
  assert.equal(dispatch({...next, previous:"fallback", id:"fallback-next"}).remaining, 0);
  dispatch({...book("archive", 5), service:"archive"});
  assert.equal(dispatch({...next, service:"archive", previous:"archive", id:"archive-next", units:6}).status, "full");
});
